"""Broaden the ADR 0008 refusal to catch the case the ADR says a test guards against:
the same measure id declared on two DIFFERENT entities. If the named test really asserted
that case is accepted, it must fail under this patch.
"""
import adss.uss as U

def _broadened(uss):
    seen = {}
    for event in uss.events:
        for measure in event.measures:
            key = measure.id                     # <- entity dropped from the key
            if key in seen:
                raise U.UssError(
                    f"{measure.id} is declared on both {seen[key]} and {event.id}."
                )
            seen[key] = event.id

U._refuse_measures_that_would_share_a_name = _broadened
PY
